    # corresponding color-2 object, stopping at the grid edge / opposite marker.
    rows = {}
    cols = {}
    for r,c in markers:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    for r, cs in rows.items():
        if len(cs) >= 2:
            for c in range(min(cs), max(cs)+1): out[r][c] = 1
    for c, rs in cols.items():
        if len(rs) >= 2:
            for r in range(min(rs), max(rs)+1): out[r][c] = 1
