        # outer/corner-like markers project to grid boundaries; middle marker projections are rays
        for r,c in markers:
            if c == left or c == right:
                for cc in range(w): out[r][cc] = 1
            if r == top or r == bot:
                for rr in range(h): out[rr][c] = 1
    return out

if __name__ == '__main__':
